"1716": {"tmdb_id": 1716, "imdb_id": "tt0080610", "title": "The Last Metro", "original_title": "Le Dernier Métro", "year": 1980, "directors": ["François Truffaut"], "countries": ["FR"], "runtime": 131, "cast": ["Catherine Deneuve", "Gérard Depardieu", "Jean Poiret", "Andréa Ferréol", "Paulette Dubost", "Jean-Louis Richard"], "overview": "In occupied Paris, an actress wed to a Jewish theater owner must keep him hidden from the Nazis while doing both of their jobs.", "poster": "https://image.tmdb.org/t/p/w342/t8KMFg9PiD9GSIHXlzast2WhZex.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/u97pGlftKRNbUn0jOoQgIobSBvb.jpg"},
"1719": {"tmdb_id": 1719, "imdb_id": "tt0058458", "title": "The Soft Skin", "original_title": "La Peau douce", "year": 1964, "directors": ["François Truffaut"], "countries": ["FR"], "runtime": 119, "cast": ["Françoise Dorléac", "Jean Desailly", "Nelly Benedetti", "Daniel Ceccaldi", "Laurence Badie", "Philippe Dumat"], "overview": "Pierre Lachenay is a well-known publisher and lecturer, married to Franca and father of Sabine. He starts a love affair with air hostess Nicole, which Pierre is hiding, but he cannot stay away from her.", "poster": "https://image.tmdb.org/t/p/w342/nYo083NgJCAQQByHzYrayxQ5xBV.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/9yPgh3v4itb0ah4XWgGM4BdAtNa.jpg"},
