"16372": {"tmdb_id": 16372, "imdb_id": "tt0055018", "title": "The Innocents", "original_title": "The Innocents", "year": 1961, "directors": ["Jack Clayton"], "countries": ["GB"], "runtime": 100, "cast": ["Deborah Kerr", "Peter Wyngarde", "Megs Jenkins", "Michael Redgrave", "Martin Stephens", "Pamela Franklin"], "overview": "In a mid-19th century Essex country house, a young governess for two children becomes convinced that the house and grounds are haunted by ghosts and that the children are being possessed.", "poster": "https://image.tmdb.org/t/p/w342/idqvLBmlEHUITMnQ0EJ6Yb5TpVw.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/oog0DJtSuPnWoSTYM7cKmAFbeuU.jpg"},
"16373": {"tmdb_id": 16373, "imdb_id": "tt0037415", "title": "The Uninvited", "original_title": "The Uninvited", "year": 1944, "directors": ["Lewis Allen"], "countries": ["US"], "runtime": 99, "cast": ["Ray Milland", "Ruth Hussey", "Gail Russell", "Donald Crisp", "Alan Napier", "Cornelia Otis Skinner"], "overview": "A pair of siblings from London purchase a surprisingly affordable, lonely cliff-top house in Cornwall, only to discover that it actually carries a ghostly price—and soon they’re caught up in a bizarre romantic triangle from beyond the grave.", "poster": "https://image.tmdb.org/t/p/w342/uwp5ahLmWliRyX3mPoLHU7BKhf5.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/poCmeIQA2xL7GnGq9PMwUcJ4AgI.jpg"},
"16375": {"tmdb_id": 16375, "imdb_id": "tt0117561", "title": "Schizopolis", "original_title": "Schizopolis", "year": 1997, "directors": ["Steven Soderbergh"], "countries": ["US"], "runtime": 99, "cast": ["Steven Soderbergh", "Scott Allen", "Betsy Brantley", "Marcus Lyle Brown", "Joe Chrest", "Silas Cooper"], "overview": "A man works for the unpleasant guru of a Scientology-like movement.", "poster": "https://image.tmdb.org/t/p/w342/9ASmg9EvWkt90dwW9YKO3NXQk8d.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/6nYzuMifSK2vOYost6j3TB97YEf.jpg"},
"16391": {"tmdb_id": 16391, "imdb_id": "tt0039192", "title": "Black Narcissus", "original_title": "Black Narcissus", "year": 1947, "directors": ["Emeric Pressburger", "Michael Powell"], "countries": ["GB"], "runtime": 100, "cast": ["Deborah Kerr", "Sabu", "David Farrar", "Flora Robson", "Esmond Knight", "Jean Simmons"], "overview": "A group of Anglican nuns, led by Sister Clodagh, are sent to a mountain in the Himalayas. The climate in the region is hostile and the nuns are housed in an odd old palace. They work to establish a school and a hospital, but slowly their focus shifts. Sister Ruth falls for a government worker, Mr. Dean, and begins to question her vow of celibacy. As Sister Ruth obsesses over Mr. Dean, Sister Clodagh becomes immersed in her own memories of love.", "poster": "https://image.tmdb.org/t/p/w342/jSbFWWbkUq5N5ikewJHNATcWnxS.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/hAyWibhJjMHyWXrMVX8N2MrEqF8.jpg"},
"16410": {"tmdb_id": 16410, "imdb_id": "tt0047094", "title": "Hobson's Choice", "original_title": "Hobson's Choice", "year": 1954, "directors": ["David Lean"], "countries": ["GB"], "runtime": 108, "cast": ["Charles Laughton", "John Mills", "Brenda De Banzie", "Daphne Anderson", "Prunella Scales", "Richard Wattis"], "overview": "A widower refuses to let his three daughters marry in order to avoid paying settlements, so they'll just have to outsmart him.", "poster": "https://image.tmdb.org/t/p/w342/kbP7EgoiOw2bIypai50JWRsqP7p.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/1GeeKCUu77eBU1ut8hTBQRmb7Iq.jpg"},
"16620": {"tmdb_id": 16620, "imdb_id": "tt0093378", "title": "La Bamba", "original_title": "La Bamba", "year": 1987, "directors": ["Luis Valdez"], "countries": ["US"], "runtime": 108, "cast": ["Lou Diamond Phillips", "Danielle von Zerneck", "Elizabeth Peña", "Rosanna DeSoto", "Esai Morales", "Joe Pantoliano"], "overview": "Los Angeles teenager Ritchie Valens becomes an overnight rock 'n' roll success in 1958, thanks to a love ballad called \"Donna\" that he wrote for his girlfriend. But as his star rises, Valens has conflicts with his jealous brother, Bob, and becomes haunted by a recurring nightmare of a plane crash just as he begins his first national tour alongside Buddy Holly.", "poster": "https://image.tmdb.org/t/p/w342/6Znulqtc7cdqlUC69HGf26Ef5fi.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/jXDanAOPM6gmypt72WlkZwrPuK0.jpg"},
