"17814": {"tmdb_id": 17814, "imdb_id": "tt0074156", "title": "Assault on Precinct 13", "original_title": "Assault on Precinct 13", "year": 1976, "directors": ["John Carpenter"], "countries": ["US"], "runtime": 91, "cast": ["Austin Stoker", "Darwin Joston", "Laurie Zimmer", "Martin West", "Tony Burton", "Charles Cyphers"], "overview": "A highway patrol officer, two criminals, and a station secretary form an unlikely alliance to defend a defunct Los Angeles precinct against a siege by a bloodthirsty street gang.", "poster": "https://image.tmdb.org/t/p/w342/RtGDEmXbSxE8NThCCY1SXFXLLw.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/dm1bqDSw3MJTjYCeuNUv122BXFp.jpg"},
