"18415": {"tmdb_id": 18415, "imdb_id": "tt0119237", "title": "Gummo", "original_title": "Gummo", "year": 1997, "directors": ["Harmony Korine"], "countries": ["US"], "runtime": 89, "cast": ["Jacob Reynolds", "Jacob Sewell", "Nick Sutton", "Chloë Sevigny", "Darby Dougherty", "Carisa Glucksman"], "overview": "Teenagers Solomon and Tummler kill time in Xenia, Ohio, a small town that has never recovered from the tornado that ravaged the community in the 1970s.", "poster": "https://image.tmdb.org/t/p/w342/tMdoCRx0XIPR5uYBwxbxR7WCNBb.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/mLdMnoIE4SjMkTkgxayaHH9DS4.jpg"},
"18513": {"tmdb_id": 18513, "imdb_id": "tt0060736", "title": "The Naked Prey", "original_title": "The Naked Prey", "year": 1965, "directors": ["Cornel Wilde"], "countries": ["US", "ZA"], "runtime": 96, "cast": ["Cornel Wilde", "Gert Van den Bergh", "Ken Gampu", "Patrick Mynhardt", "Bella Randles", "Morrison Gampu"], "overview": "A group of men are on safari. One of the party refuses to give a gift to a tribe they encounter. The tribe is offended, seizes the party, and one-by-one, kills all but one of the safari members in various creative and horrifying ways. The last surviving member is given \"The Lion's Chance\" by the tribal leader to be hunted down by a party of tribal warriors.", "poster": "https://image.tmdb.org/t/p/w342/lBm8f2eVBKUKVqrdyJTNwdfAUqi.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/m1p2f1QoD79N2YNFXDtVMQtExVG.jpg"},
