"22013": {"tmdb_id": 22013, "imdb_id": "tt0053793", "title": "Elmer Gantry", "original_title": "Elmer Gantry", "year": 1960, "directors": ["Richard Brooks"], "countries": ["US"], "runtime": 146, "cast": ["Burt Lancaster", "Jean Simmons", "Arthur Kennedy", "Dean Jagger", "Shirley Jones", "Patti Page"], "overview": "A charismatic charlatan begins a business — and eventually romantic — relationship with a roadside evangelist to sell religion to 1920s America. Based on Sinclair Lewis' novel of the same name.", "poster": "https://image.tmdb.org/t/p/w342/5vd031r08rrfSMqtB9UarwqCUOz.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/tPMHXHKGl9bFCcByKO6M5mClKnE.jpg"},
