"26928": {"tmdb_id": 26928, "imdb_id": "tt0068323", "title": "Buck and the Preacher", "original_title": "Buck and the Preacher", "year": 1972, "directors": ["Sidney Poitier"], "countries": ["US", "MX"], "runtime": 102, "cast": ["Sidney Poitier", "Harry Belafonte", "Ruby Dee", "Cameron Mitchell", "Denny Miller", "Nita Talbot"], "overview": "A wagon master and a con-man preacher help freed slaves dogged by cheap-labor agents out West.", "poster": "https://image.tmdb.org/t/p/w342/wOC45WEW18IjdXGYohqTlEP2U1j.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/4gzZmRCppUx0aXXqwfUztKukSzS.jpg"},
"26933": {"tmdb_id": 26933, "imdb_id": "tt0111019", "title": "Wild Reeds", "original_title": "Les Roseaux sauvages", "year": 1994, "directors": ["André Téchiné"], "countries": ["FR"], "runtime": 115, "cast": ["Élodie Bouchez", "Gaël Morel", "Stéphane Rideau", "Frédéric Gorny", "Michèle Moretti", "Jacques Nolot"], "overview": "As the Algerian War draws to a close, a teenager with a girlfriend starts feeling homosexual urges for two of his classmates: a country boy, and a French-Algerian intellectual.", "poster": "https://image.tmdb.org/t/p/w342/7qtoLu4rNChvS3aWBxvv5o1HWqE.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/9MbN03RE7vEn1trsdFaBdisFXPo.jpg"},
"26973": {"tmdb_id": 26973, "imdb_id": "tt0078111", "title": "Pretty Baby", "original_title": "Pretty Baby", "year": 1978, "directors": ["Louis Malle"], "countries": ["US"], "runtime": 110, "cast": ["Brooke Shields", "Keith Carradine", "Susan Sarandon", "Frances Faye", "Antonio Fargas", "Matthew Anton"], "overview": "In 1917 New Orleans, a 12-year-old girl is raised in a brothel by her prostitute mother.", "poster": "https://image.tmdb.org/t/p/w342/smBDqEIwEZbtOYdAEVpY0QYJyRG.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/nehq8TDd7WnwBnTLnvv8BQNekzW.jpg"},
"27019": {"tmdb_id": 27019, "imdb_id": "tt0071381", "title": "Céline and Julie Go Boating", "original_title": "Céline et Julie vont en bateau", "year": 1974, "directors": ["Jacques Rivette"], "countries": ["FR"], "runtime": 193, "cast": ["Juliet Berto", "Dominique Labourier", "Bulle Ogier", "Marie-France Pisier", "Barbet Schroeder", "Nathalie Asnar"], "overview": "Julie, a daydreaming librarian, meets Céline, an enigmatic magician, and together they become the heroines of a time-warping adventure involving a haunted house, psychotropic candy, and a murder-mystery melodrama.", "poster": "https://image.tmdb.org/t/p/w342/h62tGTMdVVUThFwl5b4EP18cBhb.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/b5GLJlkFFv4gIVPHAoBUQij1JL1.jpg"},
"27030": {"tmdb_id": 27030, "imdb_id": "tt0046022", "title": "The Earrings of Madame de...", "original_title": "Madame de…", "year": 1953, "directors": ["Max Ophüls"], "countries": ["FR", "IT"], "runtime": 105, "cast": ["Charles Boyer", "Danielle Darrieux", "Vittorio De Sica", "Jean Debucourt", "Jean Galland", "Mireille Perrey"], "overview": "In late 19th century France, the Countess Louise, wife of a wealthy general, sells the earrings her husband gave her on their wedding day to pay off her secret debts, then claims to have lost them. Her husband quickly learns of the deceit, which is the beginning of many tragic misunderstandings, all involving the earrings, the general, the countess, and her new lover, the Italian Baron Donati.", "poster": "https://image.tmdb.org/t/p/w342/xAgA99X8BjkCUX91ukgiK10Z6La.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/msQMXYEBHQ7zPVu0TPEm7wUSGHQ.jpg"},
"27031": {"tmdb_id": 27031, "imdb_id": "tt0061847", "title": "Samurai Rebellion", "original_title": "上意討ち 拝領妻始末", "year": 1967, "directors": ["Masaki Kobayashi"], "countries": ["JP"], "runtime": 121, "cast": ["Toshirō Mifune", "Yōko Tsukasa", "Gō Katō", "Tatsuyoshi Ehara", "Etsuko Ichihara", "Isao Yamagata"], "overview": "The mother of a feudal lord's only heir is kidnapped by the lord. Her husband and his samurai father must decide whether to accept the unjust decision, or risk death to rescue her.", "poster": "https://image.tmdb.org/t/p/w342/bKySGFUTgsZyn5i7s5htMVy4Xd2.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/rOmuV9occ2BKOJtca4JflEP7g8I.jpg"},
"27040": {"tmdb_id": 27040, "imdb_id": "tt0036154", "title": "Meshes of the Afternoon", "original_title": "Meshes of the Afternoon", "year": 1943, "directors": ["Maya Deren", "Alexander Hammid"], "countries": ["US"], "runtime": 14, "cast": ["Maya Deren", "Alexander Hammid"], "overview": "A woman returning home falls asleep and has vivid dreams that may or may not be happening in reality. Through repetitive images and complete mismatching of the objective view of time and space, her dark inner desires play out on-screen.", "poster": "https://image.tmdb.org/t/p/w342/yHjEjRU81RcxKFNU5hhiPYMzlsu.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/otRHDr3aMJboh9N4AMbuKKnlHYL.jpg"},
"27053": {"tmdb_id": 27053, "imdb_id": "tt0031514", "title": "Daybreak", "original_title": "Le jour se lève", "year": 1939, "directors": ["Marcel Carné"], "countries": ["FR"], "runtime": 93, "cast": ["Jean Gabin", "Jacqueline Laurent", "Jules Berry", "Arletty", "Mady Berry", "René Génin"], "overview": "After committing a murder, a man locks himself in his apartment and recollects the events that led him to the killing.", "poster": "https://image.tmdb.org/t/p/w342/cjbHvOHbZ2sMgHJM8P7L1Pt5wAV.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/9gEEeK9hwkxS1fEtYEAohahAWxq.jpg"},
"27064": {"tmdb_id": 27064, "imdb_id": "tt0089603", "title": "Mishima: A Life in Four Chapters", "original_title": "Mishima: A Life in Four Chapters", "year": 1985, "directors": ["Paul Schrader"], "countries": ["JP", "US"], "runtime": 121, "cast": ["Ken Ogata", "Masayuki Shionoya", "Hiroshi Mikami", "Junya Fukuda", "Yuu Tokui", "Junkichi Orimoto"], "overview": "A fictional account of the life of Japanese author Yukio Mishima, combining dramatizations of three of his novels and a depiction of the events of November 25th, 1970.", "poster": "https://image.tmdb.org/t/p/w342/4kIXsE4SwUjO0eUqpolsHNO5GLH.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/PnwQJeWhmx9wh9wWM0a0YhLmE.jpg"},
"27067": {"tmdb_id": 27067, "imdb_id": "tt0120448", "title": "The Life of Jesus", "original_title": "La Vie de Jésus", "year": 1997, "directors": ["Bruno Dumont"], "countries": ["FR"], "runtime": 96, "cast": ["David Douche", "Marjorie Cottreel", "Kader Chaatouf", "Sébastien Delbaere", "Samuel Boidin", "Steve Smagghe"], "overview": "Twenty-something Freddy is becalmed in a podunk French village where the only sign of life is the local amateur brass band and youth aimlessly roaming around the countryside on scooters. He has an intense sexual connection with his girlfriend but has no joy or passion to give her. When she falls for a handsome Arab youth a tragedy unfolds.", "poster": "https://image.tmdb.org/t/p/w342/mY7yWPN61wqpCIGVtNjInGidyJk.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/8nzazBKjnS4VlV74MKbPsnpbKaX.jpg"},
"27094": {"tmdb_id": 27094, "imdb_id": "tt0071746", "title": "Lenny", "original_title": "Lenny", "year": 1974, "directors": ["Bob Fosse"], "countries": ["US"], "runtime": 112, "cast": ["Dustin Hoffman", "Valerie Perrine", "Jan Miner", "Stanley Beck", "Frankie Man", "Rashel Novikoff"], "overview": "The story of acerbic 1960s comic Lenny Bruce, whose groundbreaking, no-holds-barred style and social commentary was often deemed by the establishment as too obscene for the public.", "poster": "https://image.tmdb.org/t/p/w342/Avhk4pGdz3YQrzqLU65icjnE6vn.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/6zqFDzIKPKyGX1jwYAiJTGvYyXz.jpg"},
