"71401": {"tmdb_id": 71401, "imdb_id": "tt0105356", "title": "The Sentinel", "original_title": "La Sentinelle", "year": 1992, "directors": ["Arnaud Desplechin"], "countries": ["FR"], "runtime": 139, "cast": ["Emmanuel Salinger", "Thibault de Montalembert", "Jean-Louis Richard", "Valérie Dréville", "Marianne Denicourt", "Jean-Luc Boutté"], "overview": "A medical intern finds himself drawn into a world of international intrigue after discovering a shrunken human head in his luggage.", "poster": "https://image.tmdb.org/t/p/w342/jPveiKaj9ujkGbqfQLIHDetRkqW.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/4zFX1eWQlkkLSU2i3iHLz5oGvHA.jpg"},
"71827": {"tmdb_id": 71827, "imdb_id": "tt0059936", "title": "Patriotism", "original_title": "憂國", "year": 1966, "directors": ["Yukio Mishima"], "countries": ["JP"], "runtime": 28, "cast": ["Yukio Mishima", "Yoshiko Tsuruoka"], "overview": "Two characters on a Noh stage dramatize the rite of love and death of Lieutenant Shinji Takeyama and his wife Reiko.", "poster": "https://image.tmdb.org/t/p/w342/qHUpRS0izdEHH9Sq2GVtO2OYCYb.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/q9XuWoakCeMyJyem2wP3uJBb8kD.jpg"},
