"86785": {"tmdb_id": 86785, "imdb_id": "tt0059459", "title": "The Moment of Truth", "original_title": "Il momento della verità", "year": 1965, "directors": ["Francesco Rosi"], "countries": ["IT", "ES"], "runtime": 108, "cast": ["Miguel Mateo 'Miguelín'", "José Gómez Sevillano", "Pedro \"Pedrucho\" Basauri", "Linda Christian", "Luque Gago", "Salvador Mateo"], "overview": "Miguel, a poor young man living in Franco's Spain becomes a bull fighter to escape poverty.", "poster": "https://image.tmdb.org/t/p/w342/nR1WuQpw11Ovpzxs7tcFyivE9pB.jpg", "backdrop": "https://image.tmdb.org/t/p/w780/5jCan3YHDyVObXApoZzihrrKe60.jpg"},
